package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
class VideoVersionDiffTest {
 private fun base()=VideoSegment(0,4000,title="Keep title")
 private fun draft(clips:List<VideoSegment> = listOf(base()),sources:List<VideoSource> = listOf(VideoSource("other","content://synthetic/other",10000)),music:VideoSoundtrack?=null,primary:Long=10000)=VideoDraft(primary,clips,0,clips[0].startMs,clips[0].startMs,clips[0].endMs,sources,music)
 @Test fun identicalDraftHasNoChangesAndNoExpandedPositions(){val a=draft();val r=VideoVersionDiff.compare(a,a.copy());assertTrue(r.identical);assertEquals(0,r.changedPositions);assertEquals(0,r.omittedPositions);assertTrue(r.changes.isEmpty());assertTrue(r.text().contains("No metadata differences"))}
 @Test fun everyRenderAndSourceCategoryIsDetectedSeparately(){val a=base();val cases=listOf(VideoVersionDiff.Field.SOURCE to a.copy(sourceId="other"),VideoVersionDiff.Field.WINDOW to a.copy(startMs=1000,endMs=5000,speed=2f),VideoVersionDiff.Field.TITLE to a.copy(title="Changed",titleStyle=VideoTitleStyle(size=.08f)),VideoVersionDiff.Field.COLOR to a.copy(grade=VideoGrade(exposure=.5f)),VideoVersionDiff.Field.FRAMING to a.copy(layout=VideoLayout(rotation=90)),VideoVersionDiff.Field.MOTION to a.copy(motion=VideoMotion(enabled=true,endZoom=1.5f,anchorEndMs=4000)),VideoVersionDiff.Field.EDGES to a.copy(fadeEdges=true),VideoVersionDiff.Field.AUDIO to a.copy(volume=.3f,audioFade=true),VideoVersionDiff.Field.CAPTIONS to a.copy(captions=listOf(VideoCaption(0,1000,"Words"))));for((field,b) in cases){val r=VideoVersionDiff.compare(draft(),draft(listOf(b)));assertEquals(listOf(field),r.changes.single().fields);assertEquals(1,r.changedPositions);assertFalse(r.identical)}}
 @Test fun captionTextTimingAndSubtitleProvenanceDifferencesAreDetected(){val c=base().copy(captions=listOf(VideoCaption(0,1000,"Old")),captionSourceUri="content://synthetic/subtitle-private");for(b in listOf(c.copy(captions=listOf(VideoCaption(0,1000,"New"))),c.copy(captions=listOf(VideoCaption(1,1000,"Old"))),c.copy(captionSourceUri="content://synthetic/another-private"))){val r=VideoVersionDiff.compare(draft(listOf(c)),draft(listOf(b)));assertEquals(listOf(VideoVersionDiff.Field.CAPTIONS),r.changes.single().fields);assertFalse(r.text().contains("content://"))}}
 @Test fun sourceIdEqualityDoesNotHideChangedImportedDocumentBinding(){val clips=listOf(base().copy(sourceId="other"));val a=draft(clips);val b=draft(clips,listOf(VideoSource("other","content://synthetic/private-new-binding",10000)));val r=VideoVersionDiff.compare(a,b);assertTrue(r.catalogChanged);assertEquals(listOf(VideoVersionDiff.Field.SOURCE),r.changes.single().fields);assertFalse(r.text().contains("content://"));assertFalse(r.text().contains("private-new-binding"))}
 @Test fun catalogAndPrimaryDurationChangesAreDetectedWithoutMediaRead(){val a=draft();val r=VideoVersionDiff.compare(a,a.copy(sources=listOf(VideoSource("other","content://synthetic/unused-changed",9000))));assertTrue(r.catalogChanged);assertFalse(r.identical);assertEquals(0,r.changedPositions);val primary=VideoVersionDiff.compare(a,draft(primary=9000));assertTrue(primary.primaryDurationChanged);assertEquals(listOf(VideoVersionDiff.Field.SOURCE),primary.changes.single().fields)}
 @Test fun sourceCatalogOrderingAloneDoesNotClaimBindingChange(){val a=draft(sources=listOf(VideoSource("one","content://synthetic/one",10000),VideoSource("two","content://synthetic/two",10000)));assertTrue(VideoVersionDiff.compare(a,a.copy(sources=a.sources.reversed())).identical)}
 @Test fun addedAndRemovedTailSlotsAreReportedByPosition(){val a=draft();val b=draft(listOf(base(),VideoSegment(4000,8000)));val added=VideoVersionDiff.compare(a,b);assertEquals(1,added.changedPositions);assertNull(added.changes.single().before);assertEquals(1,added.changes.single().index);assertEquals(4000000L,added.savedUs-added.currentUs);val removed=VideoVersionDiff.compare(b,a);assertNull(removed.changes.single().saved);assertTrue(removed.text().contains("saved has no position"))}
 @Test fun reorderingIsExplicitlyPositionalInsteadOfClaimingMoveIdentity(){val a=draft(listOf(base(),base().copy(title="Second")));val r=VideoVersionDiff.compare(a,a.copy(segments=a.segments.reversed()));assertEquals(2,r.changedPositions);assertTrue(r.changes.all{it.fields==listOf(VideoVersionDiff.Field.TITLE)});assertTrue(r.text().contains("by timeline position"))}
 @Test fun allSoundtrackPropertiesIncludingDocumentIdentityAreCompared(){val music=VideoSoundtrack("content://synthetic/music",10000);val a=draft(music=music);for(m in listOf(null,music.copy(uri="content://synthetic/other-music"),music.copy(volume=.5f),music.copy(loop=false),music.copy(startMs=1000),music.copy(endMs=9000))){val r=VideoVersionDiff.compare(a,draft(music=m));assertTrue(r.soundtrackChanged);assertEquals(0,r.changedPositions);assertFalse(r.identical);assertFalse(r.text().contains("content://"))}}
 @Test fun selectionTrimAndPlayheadChangeWithoutClaimingTimelineEdits(){val a=draft(listOf(base(),base()));for(b in listOf(a.copy(selectedClip=1),a.copy(previewPositionMs=1000),a.copy(trimStartMs=1000),a.copy(trimEndMs=3000))){val r=VideoVersionDiff.compare(a,b);assertTrue(r.selectionChanged);assertEquals(0,r.changedPositions);assertFalse(r.soundtrackChanged);assertFalse(r.identical)}}
 @Test fun maximumThousandPositionsAreCountedWithBoundedFirstHundredDetails(){val a=draft(List(1000){base()});val b=draft(List(1000){base().copy(title="Changed")});val r=VideoVersionDiff.compare(a,b);assertEquals(1000,r.changedPositions);assertEquals(100,r.changes.size);assertEquals(900,r.omittedPositions);assertEquals((0..99).toList(),r.changes.map{it.index});assertTrue(r.text().length<100000)}
 @Test fun playbackTotalsUseMicrosecondsAcrossSpeedsBeforeRounding(){val a=draft(listOf(VideoSegment(0,1001,speed=1.5f),VideoSegment(0,1001,speed=2f)));val r=VideoVersionDiff.compare(a,a.copy());assertEquals(1167833L,r.currentUs);assertEquals(r.currentUs,r.savedUs);assertTrue(r.text().contains("1.167833"))}
 @Test fun noInputsOrActualProjectHistoryAreChanged(){val p=VideoEditProject(10000);p.restore(listOf(base()));val before=p.segments;val a=draft(before);val b=draft(listOf(base().copy(title="Other")));val copyA=a.copy();val copyB=b.copy();VideoVersionDiff.compare(a,b).text();assertEquals(copyA,a);assertEquals(copyB,b);assertSame(before,p.segments);assertFalse(p.canUndo)}
}
